    src=np.zeros((31,31));src[10:20,7:22]=np.arange(150).reshape(10,15);lap=np.exp(-abs(np.arange(-30,31))/4);lap/=lap.sum();a=fftconvolve(fftconvolve(src,k,mode='full'),lap[None,:],mode='full');b=fftconvolve(fftconvolve(src,lap[None,:],mode='full'),k,mode='full');err=float(np.max(abs(a-b))/np.max(abs(a)));assert err<1e-12
    rot=fftconvolve(src.T,k.T,mode='full').T;orig=fftconvolve(src,k,mode='full');assert np.max(abs(rot-orig))<1e-10
    return dict(covariance_moment_max_error=float(np.max(abs(moment-cov))),projection_convolution_commutation_relative=err,rotation=True,full_convolution_mass_relative=float(abs(orig.sum()/src.sum()-1)))
