        for factor in [1,2]:
            dx=.03125/factor;n=(len(axis)-1)*factor+1;nodes=np.linspace(axis[0],axis[-1],n);ss=zoom(source,(n/len(source),n/len(source)),order=1,mode='nearest',grid_mode=False,prefilter=False) if factor==2 else source.copy();assert ss.shape==(n,n)
            k,_,_=gaussian(cov,dx);full=fftconvolve(ss,k,mode='full');assert abs(full.sum()/ss.sum()-1)<1e-10;startx=k.shape[0]//2;starty=k.shape[1]//2;sm=full[startx:startx+n,starty:starty+n].copy();negative=float(-np.minimum(sm,0).sum());assert negative/max(ss.sum(),1)<1e-12;sm=np.maximum(sm,0);pre=sm.sum();sm[[0,-1],:]=0;sm[:,[0,-1]]=0;loss=float(1-sm.sum()/ss.sum());assert loss<1e-6
